//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:						HE_Ramp_Gain
//	CREATOR:					Ruben Byman
// REQUIREMENTS: 		NX CPU
//
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION				DATE				SIGN						DESCRIPTION
//	 1.0.0					2024-03-19		Ruben Byman			Initial release
//	 2.0.0					2025-03-25		William Veim			Rework
//	 2.0.1					2026-01-21		Ruben Byman			Output retained
//
//================================================================================================================================
//
//			DESCRTIPTION: 	
//			Ramps the control towards the desired value over a set time
//		
//================================================================================================================================

(*************************************************************************
 *	INTERNAL VARIABLES
 *************************************************************************)
Wrk_Input := Inp_Value;

//Setter oppløsning
IF Cfg_Resolution THEN
	Resolution := 1000;
ELSE
	Resolution := 100;
END_IF;

(*************************************************************************
 *	RAMPING CONTROL
 *************************************************************************)

//Time delay to stop ramping
TON_OutputEqual(In:= (HE_ABSValue(Wrk_Output - Wrk_Input) < (HE_ABSValue(Cfg_Output_X1-Cfg_Output_X0) / Resolution)) AND NOT TON_OutputEqual.Q AND NOT (Wrk_Input = Wrk_Output), 
							PT:=DIVTIME(In1:=Cfg_StrokeTime, In2:=Resolution), ET=>ET_OutputEqual);

//Output ramping (increase / decrease)
//-----------------------------------------
IF Inp_RampStart AND NOT TON_OutputEqual.Q THEN
	TON_IncreaseOutput(PT:=DIVTIME(In1:=Cfg_StrokeTime, In2:=Resolution), ET=>ET_ChangeTime);
	TON_IncreaseOutput.In := (HE_ABSValue(Wrk_Output - Wrk_Input) >= (HE_ABSValue(Cfg_Output_X1-Cfg_Output_X0) / Resolution)) AND NOT TON_IncreaseOutput.Q;
	
	//Increase output
	IF TON_IncreaseOutput.Q AND (Wrk_Input > Wrk_Output) THEN
		Wrk_Output := Wrk_Output + (HE_ABSValue(Cfg_Output_X1-Cfg_Output_X0) / Resolution);
		
	//Decrease output
	ELSIF TON_IncreaseOutput.Q AND (Wrk_Input < Wrk_Output) THEN
		Wrk_Output := Wrk_Output - (HE_ABSValue(Cfg_Output_X1-Cfg_Output_X0) / Resolution);
	END_IF;

	//Limiting to X0/X1
	Wrk_Output:=	LIMIT(MN:=TO_REAL(MIN(Cfg_Output_X0, Cfg_Output_X1)), 
										In:=Wrk_Output, 
										MX:=TO_REAL(MAX(Cfg_Output_X0, Cfg_Output_X1)));

//Not enabled OR ramp time done
//------------------------------------
ELSE
	
	Wrk_Output := Wrk_Input;

END_IF;

(*************************************************************************
 *	UPDATING OUTPUT
 *************************************************************************)
 
Out_Output := Wrk_Output;
